//! The calendars Excel reads from tables rather than from a rule: Persian (calendar digit 0x16,
//! Windows' `CAL_PERSIAN`), whose leap years follow the equinox, not a cycle (no 33- or 2820-year
//! rule fits: the new year drifts from 21 March in 1900 to 17 March by 9999), and Um al-Qura (0x17,
//! `CAL_UMALQURA`), Saudi Arabia's month table for 1318-1500 AH. Both tables are Excel's answers,
//! generated by `rustsheet-excel-locales` (tools/) from probes/t4061-persian-new-years and
//! probes/t4061-umalqura-months; number-formats.md "Calendars of a locale tag".

use std::sync::OnceLock;

use super::{calendar_dates::real_day, date_names::hijri_ymd};

/// The days of the Persian months: six of 31, five of 30, and the rest (29, 30 in a leap year).
const PERSIAN_MONTHS: [i64; 11] = [31, 31, 31, 31, 31, 31, 30, 30, 30, 30, 30];

/// A calendar of consecutive periods (years or months) read from a table: the first period's
/// number and the day each period starts on (1899-12-30 being day 0), one more than there are
/// periods, so the last entry ends the table.
struct Periods {
    first: i32,
    starts: Vec<i64>,
}

impl Periods {
    /// The period holding `day` and the day it starts on, `None` outside the table.
    fn find(&self, day: i64) -> Option<(i32, i64)> {
        let after = self.starts.partition_point(|start| *start <= day);
        let index = after.checked_sub(1)?;
        if after == self.starts.len() {
            return None;
        }
        Some((
            self.first + i32::try_from(index).ok()?,
            *self.starts.get(index)?,
        ))
    }
}

/// Parses a table file: after the comments, a line `<first period> <first day>`, then lines of a
/// period number and one digit per period (`unit` periods long when the digit is 0, one more when
/// it is 1). A malformed table reads as empty, so every date is outside it.
fn parse(text: &str, unit: impl Fn(usize) -> i64) -> Periods {
    let mut lines = text
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'));
    let header = lines.next().and_then(|line| {
        let (first, day) = line.split_once('\t')?;
        Some((first.parse().ok()?, day.parse::<i64>().ok()?))
    });
    let Some((first, mut day)) = header else {
        return Periods {
            first: 0,
            starts: Vec::new(),
        };
    };
    let mut starts = vec![day];
    let digits = lines.filter_map(|line| line.split_once('\t').map(|(_, bits)| bits));
    for (index, bit) in digits.flat_map(str::chars).enumerate() {
        day += unit(index) + i64::from(bit == '1');
        starts.push(day);
    }
    Periods { first, starts }
}

fn persian_years() -> &'static Periods {
    static YEARS: OnceLock<Periods> = OnceLock::new();
    YEARS.get_or_init(|| parse(include_str!("persian_years.txt"), |_| 365))
}

fn um_al_qura_months() -> &'static Periods {
    static MONTHS: OnceLock<Periods> = OnceLock::new();
    MONTHS.get_or_init(|| parse(include_str!("um_al_qura_months.txt"), |_| 29))
}

/// The Persian date of 1900-system `serial_1900` (`[$-160409]yyyy-mm-dd` of 2023-03-15 is
/// "1401-12-24", of 1900-01-01 "1278-10-11", of 9999-12-31 "9378-10-13"; serial 60 is
/// `#VALUE!` as for every converted calendar, `calendar_dates::real_day`). The last tabled year
/// runs past 9999-12-31.
pub(crate) fn persian_ymd(serial_1900: i64) -> Option<(i32, u32, u32)> {
    let day = real_day(serial_1900)?;
    let years = persian_years();
    let last = years.starts.last().copied()?;
    let (year, start) = years.find(day).or_else(|| {
        let year = years.first + i32::try_from(years.starts.len()).ok()? - 1;
        (day >= last).then_some((year, last))
    })?;
    let mut rest = day - start;
    let mut month = 1;
    for length in PERSIAN_MONTHS {
        if rest < length {
            break;
        }
        rest -= length;
        month += 1;
    }
    Some((year, month, u32::try_from(rest + 1).ok()?))
}

/// The Um al-Qura date of 1900-system `serial_1900`: Excel's month table from 1 Muharram 1318
/// (1900-04-30) to the end of 1500 (2077-11-15), the tabular Hijri date of calendar digit 6
/// before and after it (`[$-170409]yyyy-mm-dd` of 1900-01-01 is "1317-08-29", of 2077-11-16
/// "1501-01-01"; probes/t4061-umalqura-months, t4061-hijri-variant-dates).
pub(crate) fn um_al_qura_ymd(serial_1900: i64) -> Option<(i32, u32, u32)> {
    let day = real_day(serial_1900)?;
    let Some((index, start)) = um_al_qura_months().find(day) else {
        return hijri_ymd(serial_1900);
    };
    let months = index - um_al_qura_months().first;
    let year = um_al_qura_months().first + months.div_euclid(12);
    let month = u32::try_from(months.rem_euclid(12)).ok()? + 1;
    Some((year, month, u32::try_from(day - start + 1).ok()?))
}

#[cfg(test)]
mod tests {
    use super::{persian_ymd, um_al_qura_ymd};

    #[test]
    fn persian_dates() {
        // probes/t4061-persian-and-hijri-variant C2, C10 and A124 (2023-03-15).
        assert_eq!(persian_ymd(1), Some((1278, 10, 11)));
        assert_eq!(persian_ymd(45000), Some((1401, 12, 24)));
        assert_eq!(persian_ymd(2_958_465), Some((9378, 10, 13)));
        assert_eq!(persian_ymd(60), None);
    }

    #[test]
    fn um_al_qura_dates() {
        // probes/t4061-umalqura-months B1, B3, B4; 2023-03-15 is 1444-08-23 under both.
        assert_eq!(um_al_qura_ymd(1), Some((1317, 8, 29)));
        assert_eq!(um_al_qura_ymd(121), Some((1318, 1, 1)));
        assert_eq!(um_al_qura_ymd(45000), Some((1444, 8, 23)));
        assert_eq!(um_al_qura_ymd(64_970), Some((1501, 1, 1)));
    }
}
